select public.prepify_load_bank('English', 10, $j$[["The poem \"Two Mothers Remembered\" is written by:",["Joann Snow Duncanson","Robert Frost","Alfred Tennyson","Emily Dickinson"],"A",1,0,"163dc42020af"],["The central idea of \"Two Mothers Remembered\" is:",["gratitude and love for two mothers, one who gave birth and one who raised the child","a journey to the mountains","the life of a soldier","the beauty of nature"],"A",3,0,"2b72a5eb001c"],["A mother who raises a child who was not born to her is called an:",["adoptive mother","aunt","teacher","neighbour"],"A",1,0,"51b5d2be78cd"],["The main feeling expressed in the poem is:",["gratitude","anger","fear","jealousy"],"A",1,0,"cebb13ce1f3e"],["\"Gratitude\" means:",["the feeling of being thankful","a feeling of hatred","a kind of pride","a feeling of boredom"],"A",1,0,"624d6fc616d7"],["Choose the synonym of \"nurture\":",["Care for and bring up","Ignore","Punish","Abandon"],"A",3,0,"6cf39fa322ce"],["Choose the antonym of \"remember\":",["Recall","Recollect","Forget","Memorize"],"C",1,0,"216809873a8e"],["Choose the correct spelling:",["Gratitude","Gratetude","Gratitued","Graditude"],"A",1,0,"1a7f612fca32"],["Aliya was raised lovingly by her aunt after her own mother died. Writing a poem thanking both women would express the same feelings as:",["\"Two Mothers Remembered\"","a travel diary","a business letter","a news report"],"A",3,1,"f897ad99a809"],["In \"She loved me dearly\", \"dearly\" is:",["a noun","an adjective","an adverb","a verb"],"C",1,0,"ffd8e7d9fde1"],["Choose the passive voice of \"My mother raised me.\":",["I am raised by my mother.","I was raised by my mother.","I have raised my mother.","I was raising by my mother."],"B",3,0,"61d55a11fe81"],["Fill in the blank: I am grateful ___ my mother for her love.",["at","to","on","with"],"B",3,0,"6b583c998d1a"],["Choose the correct sentence:",["A mother's love are special.","A mother's love is special.","A mother's love be special.","A mother's love were special."],"B",1,0,"fa13d229dd58"],["Which sentence is in the past tense?",["She cares for me.","She cared for me.","She will care for me.","She is caring for me."],"B",1,0,"430c95465feb"],["Choose the synonym of \"affection\":",["Love","Hatred","Anger","Envy"],"A",1,0,"a98895b4a04f"],["Choose the indirect speech of: She said, \"I will always love you.\"",["She said that she would always love me.","She said that I will always love you.","She says that she would always love me.","She said that she will always loved me."],"A",5,0,"2ac39a323428"],["Choose the correct way to write \"the love of my mother\":",["my mothers love","my mother's love","my mothers's love","my mother love"],"B",5,0,"75af3af0cfe4"],["Choose the plural of \"mother-in-law\":",["mother-in-laws","mothers-in-law","mothers-in-laws","mother-ins-law"],"B",5,0,"e281cb6db416"],["Choose the correctly punctuated sentence:",["\"Thank you, Mother,\" I said.","\"Thank you Mother\" I said.","\"thank you, mother,\" I said.","Thank you, Mother, I said."],"A",3,0,"bec99effebfe"],["A student gives her mother a card saying, \"You gave me love that I can never repay.\" The word \"repay\" means:",["pay back","take away","borrow","forget"],"A",3,1,"540955e3a495"],["The word \"sacrifice\" means:",["giving up something valuable for the sake of others","taking something from others","winning a game","a kind of gift shop"],"A",3,0,"3e6863c685a1"],["Choose the adjective in: \"She has a gentle heart.\"",["She","has","gentle","heart"],"C",1,0,"78030e7b1fc5"],["Choose the antonym of \"selfless\":",["Generous","Kind","Selfish","Caring"],"C",1,0,"361d828c1764"],["Fill in the blank: Both mothers played ___ important role in the child's life.",["a","an","the","no article"],"B",5,0,"76342fb610b5"],["Choose the synonym of \"cherish\":",["Treasure","Neglect","Destroy","Forget"],"A",3,0,"3b3d31951b41"],["Which sentence shows gratitude?",["Thank you for everything you have done for me.","Leave me alone.","I don't care.","Why did you do that?"],"A",1,0,"f7a1211a9b76"],["The word \"remembered\" in the title shows that the poet is:",["thinking back with love about the two mothers","forgetting the mothers","writing a letter of complaint","describing a holiday"],"A",3,0,"e972be00e161"],["Choose the noun related to \"grateful\":",["Gratefully","Gratitude","Great","Grated"],"B",5,0,"1e98c9a0aabd"],["Choose the noun related to \"generous\":",["Generously","Generosity","General","Generate"],"B",5,0,"1e98c9a0aabd"],["Which sentence expresses thanks?",["I am so grateful for your help.","Go away.","I don't mind.","Who asked you?"],"A",1,0,"f7a1211a9b76"],["Choose the synonym of \"love\":",["Affection","Hatred","Anger","Envy"],"A",1,0,"a98895b4a04f"],["Choose the antonym of \"selfish\":",["Greedy","Mean","Selfless","Proud"],"C",1,0,"361d828c1764"],["Choose the antonym of \"forget\":",["Ignore","Lose","Remember","Neglect"],"C",1,0,"216809873a8e"],["The feeling that runs through \"Two Mothers Remembered\" is one of:",["gratitude and love","anger","fear","jealousy"],"A",1,0,"cebb13ce1f3e"],["Choose the indirect speech of: He said, \"I will always help you.\"",["He said that he would always help me.","He said that I will always help you.","He says that he would always help me.","He said that he will always helped me."],"A",5,0,"2ac39a323428"],["Choose the correct sentence:",["A father's care are precious.","A father's care is precious.","A father's care be precious.","A father's care were precious."],"B",1,0,"fa13d229dd58"],["A boy writes to his grandmother, \"I can never repay your kindness.\" Here \"repay\" means:",["pay back","take away","borrow","forget"],"A",3,1,"540955e3a495"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 11, $j$[["\"The Metamorphosis\" was written by:",["Franz Kafka","Charles Dickens","Leo Tolstoy","Mark Twain"],"A",1,0,"6cb83e4803ba"],["The main character of \"The Metamorphosis\" is:",["Gregor Samsa","Oliver Twist","Tom Sawyer","Robinson Crusoe"],"A",1,0,"45a1f9bc7745"],["At the start of the story, Gregor wakes up to find that he has turned into:",["a giant insect","a bird","a dog","a stone statue"],"A",1,0,"abe48195ba1e"],["Before his transformation, Gregor worked as a:",["travelling salesman","doctor","teacher","farmer"],"A",3,0,"2288666d9751"],["Gregor worked hard mainly to:",["support his family and pay off their debts","become famous","travel the world","buy a new house for himself"],"A",3,0,"2d50b0727491"],["\"Metamorphosis\" means:",["a complete change of form","a long journey","a family meeting","a business trip"],"A",3,0,"cdedf89bc2bd"],["Gregor's sister, who cares for him at first, is named:",["Grete","Anna","Maria","Clara"],"A",3,0,"8e7179d501f2"],["Gregor's father injures him by throwing:",["apples","stones","books","shoes"],"A",3,0,"ba876a264d95"],["The story mainly shows how Gregor's family:",["slowly stops caring for him once he can no longer support them","becomes richer because of him","takes him to a doctor at once","moves to another country with him"],"A",5,0,"1f2b4be0ab47"],["\"The Metamorphosis\" was originally written in:",["German","French","English","Russian"],"A",3,0,"75b863ed9eeb"],["A worker who supported his family is ignored by them once he falls ill and cannot earn. This situation is most like the story of:",["Gregor Samsa","the eagle","the Brooklyn Bridge","Jeff Bezos"],"A",3,1,"03223de32f91"],["Choose the synonym of \"transform\":",["Change","Remain","Stay","Keep"],"A",1,0,"40328069a840"],["Choose the antonym of \"sympathy\":",["Pity","Kindness","Indifference","Care"],"C",3,0,"15f1ffcaf399"],["Choose the correct spelling:",["Metamorphosis","Metamorfosis","Metamorphasis","Metammorphosis"],"A",5,0,"dd53a1208300"],["In \"Gregor woke up suddenly\", \"suddenly\" is:",["an adjective","an adverb","a noun","a verb"],"B",1,0,"e972604f5f2a"],["Choose the passive voice of \"The family locked the door.\":",["The door is locked by the family.","The door was locked by the family.","The door has locked the family.","The door was locking by the family."],"B",3,0,"694d990fe202"],["Fill in the blank: Gregor was worried ___ his job.",["at","about","on","with"],"B",3,0,"83cbbbf6dd05"],["Choose the correct sentence:",["Gregor were a salesman.","Gregor was a salesman.","Gregor be a salesman.","Gregor are a salesman."],"B",1,0,"a2a4b52e247c"],["Which sentence is in the past perfect tense?",["Gregor had turned into an insect.","Gregor turns into an insect.","Gregor is turning into an insect.","Gregor will turn into an insect."],"A",3,0,"db5001001184"],["Choose the synonym of \"burden\":",["Load","Gift","Relief","Joy"],"A",1,0,"9f9bafca4259"],["Choose the indirect speech of: Grete said, \"We must get rid of it.\"",["Grete said that they had to get rid of it.","Grete said that we must get rid of it.","Grete says that they had to get rid of it.","Grete said that they must got rid of it."],"A",5,0,"488d6292fd2d"],["\"Alienation\" in the story refers to Gregor feeling:",["isolated and cut off from others","very popular","rich and powerful","brave and strong"],"A",5,0,"84a372aa747a"],["Choose the adjective in: \"Gregor felt a sharp pain.\"",["Gregor","felt","sharp","pain"],"C",1,0,"1dfe9afc22f4"],["Choose the antonym of \"cruel\":",["Harsh","Kind","Rough","Mean"],"B",1,0,"4640742cda71"],["Choose the correctly punctuated sentence:",["\"What has happened to me?\" he thought.","\"What has happened to me.\" he thought?","What has happened to me? he thought.","\"what has happened to me?\" he thought."],"A",3,0,"e90a362f500b"],["A reader feels sad for Gregor because his family treats him coldly after he changes. The reader is feeling:",["sympathy","jealousy","anger at Gregor","boredom"],"A",3,1,"8a687bc24b8c"],["Choose the plural of \"family\":",["familys","families","familyes","familis"],"B",1,0,"00322657022f"],["The word \"vermin\" in the story describes:",["small harmful creatures such as insects","a kind of fruit","a family member","a room in the house"],"A",5,0,"30d99313c51e"],["Choose the plural of \"story\":",["storys","stories","storyes","storis"],"B",1,0,"00322657022f"],["In \"Grete opened the door quietly\", the word \"quietly\" is:",["an adjective","an adverb","a noun","a verb"],"B",1,0,"e972604f5f2a"],["Choose the synonym of \"load\":",["Burden","Gift","Relief","Joy"],"A",1,0,"9f9bafca4259"],["Choose the adjective in: \"The family lived in a small flat.\"",["family","lived","small","flat"],"C",1,0,"1dfe9afc22f4"],["Choose the passive voice of \"Grete fed Gregor.\":",["Gregor is fed by Grete.","Gregor was fed by Grete.","Gregor has fed Grete.","Gregor was feed by Grete."],"B",3,0,"694d990fe202"],["Choose the antonym of \"indifference\":",["Coldness","Neglect","Sympathy","Boredom"],"C",3,0,"15f1ffcaf399"],["In \"The Metamorphosis\", Gregor supported his family by working as a:",["travelling salesman","doctor","teacher","farmer"],"A",1,0,"2288666d9751"],["A reader feels pity for Gregor when his family shuts him away. This feeling is:",["sympathy","jealousy","pride","boredom"],"A",3,1,"8a687bc24b8c"]]$j$::jsonb, true);
select public.prepify_load_bank('English', 12, $j$[["\"Good Health and Well-being\" is which United Nations Sustainable Development Goal?",["Goal 1","Goal 3","Goal 5","Goal 10"],"B",3,0,"77e1af14ab35"],["A \"balanced diet\" is one that:",["contains the right amounts of all nutrients","contains only sweets","skips all meals","contains only meat"],"A",1,0,"3b1ce173db3d"],["Regular physical exercise mainly helps to:",["keep the body fit and healthy","make people lazy","weaken the heart","cause illness"],"A",1,0,"95ab123b4ff6"],["\"Hygiene\" means:",["practices that keep us clean and prevent disease","a type of medicine","a kind of sport","a hospital building"],"A",1,0,"ab9d1673f7e2"],["Washing hands before eating mainly helps to:",["prevent the spread of germs","make food taste better","save water","cool the body"],"A",1,0,"6307e2444809"],["\"Well-being\" means:",["the state of being healthy, comfortable and happy","a type of well for water","a kind of illness","a hospital ward"],"A",3,0,"c1bca18df7d0"],["Vaccination protects people by:",["helping the body build immunity against diseases","causing diseases","replacing food","curing broken bones"],"A",3,0,"e785683b06b7"],["Hassan sleeps only four hours a night, eats junk food and never exercises. He often feels tired. What should he change first?",["Get enough sleep, eat healthy food and exercise","Eat more junk food","Sleep even less","Stop drinking water"],"A",3,1,"53134f315ce9"],["Choose the synonym of \"fit\":",["Healthy","Weak","Ill","Tired"],"A",1,0,"d67c8894446b"],["Choose the antonym of \"healthy\":",["Sick","Strong","Active","Fresh"],"A",1,0,"4d1ec5901c60"],["Choose the correct spelling:",["Nutrition","Nutricion","Nutritian","Nutrishun"],"A",1,0,"039984ef6d12"],["In \"Exercise daily to stay healthy\", the sentence is:",["a command","a question","an exclamation","a statement of the past"],"A",1,0,"7abcb1329ab1"],["Choose the passive voice of \"Doctors treat patients.\":",["Patients are treated by doctors.","Patients were treated by doctors.","Patients treated by doctors.","Patients are treating by doctors."],"A",3,0,"d6aa0d4f7887"],["Fill in the blank: Smoking is harmful ___ health.",["at","to","for","on"],"B",3,0,"296be7b52166"],["Choose the correct sentence:",["Fruits is good for health.","Fruits are good for health.","Fruits be good for health.","Fruits was good for health."],"B",1,0,"075834a87bd1"],["Which sentence is in the present continuous tense?",["She exercises daily.","She is exercising now.","She exercised yesterday.","She will exercise tomorrow."],"B",1,0,"f9f25401d75a"],["\"Mental health\" refers to a person's:",["emotional and psychological well-being","height and weight only","eyesight","physical strength only"],"A",3,0,"41962eebf5bd"],["A student feels stressed before exams and talks to a counsellor, sleeps well and takes short breaks. She is looking after her:",["mental health","eyesight only","teeth","posture"],"A",3,1,"f55249e456dc"],["Choose the synonym of \"nutritious\":",["Healthy and nourishing","Harmful","Tasteless","Spoiled"],"A",3,0,"44a0ab94bed0"],["Choose the indirect speech of: The doctor said, \"Drink plenty of water.\"",["The doctor advised us to drink plenty of water.","The doctor said that drink plenty of water.","The doctor says to drank plenty of water.","The doctor advised that we drank plenty of water always."],"A",5,0,"6ea3cec569ca"],["Choose the word that is an adjective:",["Health","Healthy","Healthily","Heal"],"B",1,0,"102ff32870e4"],["Choose the antonym of \"cure\":",["Heal","Treat","Cause disease","Remedy"],"C",3,0,"8034eb279728"],["Choose the correct article: An apple ___ day keeps the doctor away.",["a","an","the","no article"],"A",1,0,"517f73e28af8"],["Choose the correctly punctuated sentence:",["Eat fruits, vegetables, and whole grains.","Eat fruits vegetables and whole grains.","Eat, fruits, vegetables and whole grains","eat fruits, vegetables, and whole grains."],"A",1,0,"61140fc16936"],["Choose the plural of \"tooth\":",["tooths","teeth","teeths","toothes"],"B",1,0,"1a35cc804074"],["A town has dirty drinking water and many children fall ill with diarrhoea. Which step would best improve their health?",["Providing clean, safe drinking water","Building more shops","Closing the schools","Selling more soft drinks"],"A",3,1,"8563c03ff850"],["Choose the synonym of \"prevent\":",["Stop","Allow","Encourage","Cause"],"A",1,0,"50dcc0440e5a"],["Which word is an adverb?",["Regular","Regularly","Regularity","Regulate"],"B",1,0,"f704a3c1ec95"],["Fill in the blank: Prevention is better ___ cure.",["then","than","that","from"],"B",1,0,"0024cb228203"],["\"Sedentary lifestyle\" means a life with:",["very little physical activity","a lot of sports","frequent travel","healthy eating"],"A",5,0,"831c92e5a535"],["Choose the indirect speech of: The coach said, \"Warm up before running.\"",["The coach advised us to warm up before running.","The coach said that warm up before running.","The coach says to warmed up before running.","The coach said that we warm up before running yesterday."],"A",5,0,"6ea3cec569ca"],["Which sentence is in the present continuous tense?",["He jogs daily.","He is jogging now.","He jogged yesterday.","He will jog tomorrow."],"B",1,0,"f9f25401d75a"],["Choose the passive voice of \"Nurses care for patients.\":",["Patients are cared for by nurses.","Patients were cared for by nurses.","Patients cared for by nurses.","Patients are care for by nurses."],"A",3,0,"d6aa0d4f7887"],["Choose the synonym of \"stop\":",["Prevent","Allow","Encourage","Cause"],"A",1,0,"50dcc0440e5a"],["Choose the correct sentence:",["Vegetables is good for health.","Vegetables are good for health.","Vegetables be good for health.","Vegetables was good for health."],"B",1,0,"075834a87bd1"],["A person who sits at a desk all day and rarely walks or exercises has a:",["sedentary lifestyle","active lifestyle","balanced diet","healthy routine"],"A",5,1,"831c92e5a535"],["Washing hands before eating is an example of good:",["hygiene","exercise","medicine","sleep"],"A",1,0,"ab9d1673f7e2"],["Choose the correct article: She eats ___ orange every morning.",["a","an","the","no article"],"B",1,0,"517f73e28af8"]]$j$::jsonb, true);
select public.prepify_load_bank('Maths', 1, $j$[["Let Q represent the set of Rational numbers and Q' represent the set of Irrational numbers. What is the value of the operation Q ∩ Q'?",["{0}","R","∅","Z"],"C",3,0,"a0cfe4f11a9a"],["Which of the following numbers belongs strictly to the set of Non-Integer Rational Numbers?",["-12","0","- 13/25","√11"],"C",3,0,"a9596700d62d"],["If a number x can be represented as a decimal that is non-terminating and non-recurring, to which set does it belong?",["Natural Numbers (N)","Integers (Z)","Rational Numbers (Q)","Irrational Numbers (Q')"],"D",3,1,"27e28338168a"],["According to the textbook layout, the set of Whole Numbers (W) is formed by taking the union of which two components?",["Negative Integers and Natural Numbers","The element {0} and the set of Natural Numbers (N)","Rational Numbers and Irrational Numbers","Non-integer fractions and Positive Integers"],"B",3,0,"01c4450dc013"],["Which of the following numbers is classified as a rational number that can be expressed as a terminating decimal?",["1/3","7/8","√2","-π"],"B",3,0,"a72e579d1e43"],["Why is the square root of any non-perfect square integer (such as √11 or √23) automatically irrational?",["Because its value on a number line is always less than zero.","Because it cannot be written as a terminating or repeating/recurring decimal representation.","Because it does not contain a base value.","Because it is a whole number multiple of zero."],"B",3,0,"856c37fe17ca"],["What is the structural difference between an open interval like -6 < x < 4 and a closed interval boundary on the real number line?",["Open intervals only apply to irrational numbers.","Open intervals completely exclude the exact boundary value numbers from the solution set.","Closed intervals require the use of infinity symbols.","Open intervals cannot be translated into algebraic notation."],"B",3,0,"ccb71062479b"],["Let x = -0.3̅ (or -0.333...). What is its precise structural classification?",["Irrational number, because the decimal string continues to infinity without stopping.","Integer, because it lies directly on the left side of the zero origin point.","Rational number, because it features a non-terminating, recurring decimal pattern.","Natural number, because it belongs to a predictable sequence."],"C",3,0,"dd2546a474bf"],["Which statement about the number 0 is universally true based on the properties outlined in Unit 1?",["It is the multiplicative identity of real numbers.","It belongs to the set of Natural Numbers (N).","It is the additive identity of real numbers.","It is an irrational number because it has no value."],"C",3,0,"d3605cf393ce"],["Every natural number is also automatically a member of which of the following sets?",["Negative Integers","Non-Integer Rational Numbers","Irrational Numbers","Integers, Whole Numbers and Rational Numbers"],"D",3,0,"2e07dbcf84e3"],["Which of the following numbers is a real number that is neither rational nor irrational?",["√8","-4.5","There is no such number; every real number must be either rational or irrational.","0"],"C",3,0,"d10cc0b044f1"],["If a set contains all values of x such that x > -4, which statement describes its true visual boundary configuration on a number line?",["A solid dot at -4 with a shaded arrow extending infinitely to the left.","A hollow circle at -4 with a shaded arrow extending infinitely to the right.","A solid dot at 0 pointing towards -4.","A shaded segment trapped exclusively between -4 and 0."],"B",3,1,"6471c8a64db5"],["The coordinate value point designated as the structural \"origin\" on a standard geometric number line corresponds to which real number?",["1","-1","0","∞"],"C",3,0,"790f9eae2495"],["Which of the following represents an irrational number located between the positive integers 2 and 3?",["7/8","√2","√8","4 1/2"],"C",3,0,"47afbcbfa5f7"],["What real number property is exemplified by the expression: 4 + (6 + 8) = (4 + 6) + 8?",["Commutative Property with respect to Addition","Associative Property with respect to Addition","Distributive Property of Multiplication over Addition","Closure Property with respect to Addition"],"B",3,0,"6c081cb63dab"],["Which of the following statements perfectly captures the operational rule of the Additive Inverse property?",["a . 1 = a","a + (-a) = 0","a . 1/a = 1","a . b = 1"],"B",3,0,"233af3dc499b"],["Which real number is identified as the only value that does not possess a multiplicative inverse?",["1","-1","0","Every real number has a multiplicative inverse."],"C",3,0,"130ca946f64b"],["What mathematical property justifies the step: (x + 2) + y = y + (x + 2)?",["Associative Property of Addition","Commutative Property of Addition","Distributive Property","Reflexive Property of Equality"],"B",3,0,"9d3dd2c4ce83"],["If 14 × 1/14 = 1, which real number property has been actively applied?",["Multiplicative Identity Property","Multiplicative Inverse Property","Cancellation Property","Closure Property"],"B",3,0,"b6126a708659"],["What is the product of any real number a multiplied by the additive identity?",["a","1","0","-a"],"C",3,0,"7b81fc806139"],["Which property is defined as: a(b + c) = ab + ac for all real numbers a, b and c?",["Associative Property of Multiplication","Distributive Property of Multiplication over Addition","Commutative Property of Multiplication","Symmetric Property of Equality"],"B",3,0,"b4bebcbf94d8"],["The fact that adding any two real numbers together (a + b ∈ R) will always produce another perfectly valid real number is known as the:",["Identity Property","Closure Property with respect to Addition","Transitive Property","Distributive Property"],"B",3,0,"7205fdc361f3"],["What property is highlighted by the equation: 6 × 4 = 4 × 6?",["Commutative Property with respect to Multiplication","Associative Property with respect to Multiplication","Multiplicative Identity Property","Closure Property of Multiplication"],"A",3,0,"84329d61a9d9"],["What is the value of the expressions evaluated using the distributive property: 32 (1/8 + 1/4 )",["8","10","12","16"],"C",3,0,"96de323c3caf"],["If (0.2) . 5 = 1, then 0.2 and 5 are related to each other as:",["Additive Inverses","Multiplicative Inverses","Additive Identities","Multiplicative Identities"],"B",3,0,"4e66cf9cdf6f"],["What property justifies the following algebraic statement: a . 1 = 1 . a = a?",["Multiplicative Inverse Property","Multiplicative Identity Property","Commutative Property of Addition","Trichotomy Property"],"B",3,0,"e7dd3393ab6f"],["Which of the following operations is not associative over the set of real numbers?",["Addition","Multiplication","Subtraction","Both Addition and Multiplication are non-associative."],"C",3,0,"22eb4e46a74a"],["What is the additive inverse of the number 0?",["1","-1","0","It does not exist."],"C",3,0,"e1c17ccd6a5e"],["If a < b and both share the same sign, what happens to their reciprocals?",["1/a< 1/b","1/a > 1/b","1/a = 1/b","The relationship stays exactly the same."],"B",3,1,"169ab962ba35"],["What happens to the inequality sign if a negative number is multiplied on both sides?",["The inequality sign remains completely unchanged.","The inequalities are reversed.","The inequality changes into an equals sign.","The entire mathematical expression becomes zero."],"B",3,0,"85fb2b30c80c"],["The multiplicative identity of real numbers is:",["0","1","−1","It does not exist"],"B",3,0,"e1c17ccd6a5e"],["The step (3 × x) × y = 3 × (x × y) uses the:",["commutative property of multiplication","associative property of multiplication","distributive property","closure property"],"B",3,0,"9d3dd2c4ce83"],["Since 7 + (−7) = 0, the numbers 7 and −7 are:",["additive inverses","multiplicative inverses","additive identities","reciprocals"],"A",3,0,"233af3dc499b"],["If (0.25) × 4 = 1, then 0.25 and 4 are:",["additive inverses","multiplicative inverses","additive identities","equal numbers"],"B",3,0,"4e66cf9cdf6f"],["Any real number multiplied by 0 gives:",["the number itself","1","0"